import {effectiveTracks,provisionalTracks,SIGNAL_LABELS} from './evidence.js?v=1.1.1';
import {csvCell,REGIONS} from './core.js?v=1.1.1';
import {placementOf,OUTCOMES} from './placement.js?v=1.1.1';
export const CSV_HEADERS=['Name','Doctoral institution','Doctoral program','Training region','North American research rank (UTD four journals, 2021–2025)','Research track IDs','Research fields','Research topics','Research methods','Job market paper','JMP verification evidence (original text)','JMP source URL','Personal website','CV URL','Job market cycle','Source roster year','First job start year','Graduation year','First employer','First job title','Selected outcome basis','Selected employer','Selected job title','Selected outcome category','Selected destination region','Final arrangement start year','Final arrangement status','Final arrangement evidence (original text)','Undergraduate institution','Undergraduate region','Publicly confirmed Chinese citizenship','Self-reported Chinese heritage','Original source notes','Source URLs','Checked on','Research classification mode','Research tracks used for filtering','Provisional research tracks','Provisional classification rationale (original notes)','Provisional classification source URLs','Regional public events (original evidence)','Job family','Tenure status','Tenure evidence status','Outcome evidence basis','Field evidence IDs','Original research topic text','Original research method text','Export scope metadata'];
export function csvRows(records,basis='final',researchMode='standard',metadata={}){
  return records.map(r=>{const p=placementOf(r,basis);return [r.name,r.school,r.program,REGIONS[r.origin],r.origin_rank,r.tracks.join('; '),r.fields.join('; '),r.topics.join('; '),r.methods.join('; '),r.jmp,r.jmp_evidence,r.jmp_url,r.homepage,r.cv_url,r.market_cycle,r.source_cohort_year,r.placement_year,r.graduation_year,r.destination,r.role,basis,p.destination,p.role,OUTCOMES[p.category],REGIONS[p.destination_region]||p.destination_region,r.final_placement?.year,r.final_placement?.status,r.final_placement?.evidence,r.undergraduate?.institution,REGIONS[r.undergraduate?.region]||'Unverified',r.identity?.chinese_national?.value||'unknown',r.identity?.chinese_heritage?.value||'unknown',r.notes,r.sources.map(s=>s.url).join(' | '),r.checked_at,researchMode,effectiveTracks(r,researchMode).join('; '),provisionalTracks(r).join('; '),r.research_inference?.reason,r.research_inference?.source_urls.join(' | '),(r.regional_signals||[]).map(s=>[SIGNAL_LABELS[s.kind],s.region,s.observed_date,s.institution,s.evidence,s.source_url].join(' · ')).join(' | '),p.job_family,p.tenure_status,p.tenure_evidence_status,p.basis,(r.claim_ids||[]).join('; '),(r.topics_raw||r.topics).join('; '),(r.methods_raw||r.methods).join('; '),JSON.stringify(metadata)]});
}
export function buildCsv(records,basis='final',researchMode='standard',metadata={}){return '\uFEFF'+[CSV_HEADERS,...csvRows(records,basis,researchMode,metadata)].map(row=>row.map(csvCell).join(',')).join('\r\n');}
